-- Generated by HyprMod

-- Environment
hl.env("XCURSOR_THEME", "Volantes-hyprcursor")
hl.env("XCURSOR_SIZE", "24")

-- Settings
hl.config({
    cursor = {
        hide_on_key_press = false,
    },
    decoration = {
        blur = {
            popups = true,
            size = 5,
        },
    },
    general = {
        allow_tearing = true,
        border_size = 1,
        gaps_in = 3,
        gaps_out = 10,
        layout = "dwindle",
    },
    input = {
        accel_profile = "flat",
        numlock_by_default = true,
        scroll_factor = 0.1,
        sensitivity = 0.15,
    },
    misc = {
        animate_manual_resizes = true,
        animate_mouse_windowdragging = true,
        vrr = 1,
    },
})

-- Bezier curves
hl.curve("easeInOutCubic", { type = "bezier", points = { {0.65, 0.0}, {0.35, 1.0} } })
hl.curve("skibi", { type = "bezier", points = { {1.0, -0.02}, {0.0, 1.01} } })

-- Animations
hl.animation({
    leaf = "windows",
    enabled = true,
    speed = 3.5,
    bezier = "skibi",
})
hl.animation({
    leaf = "borderangle",
    enabled = true,
    speed = 1.0,
    bezier = "default",
})
hl.animation({
    leaf = "workspaces",
    enabled = true,
    speed = 4.4,
    bezier = "easeInOutCubic",
    style = "slidefade",
})

-- Monitors
hl.monitor({
    output = "HDMI-A-2",
    disabled = false,
    mode = "2560x1440@59.95Hz",
    position = "3880x20",
    scale = 1.33,
    cm = "srgb",
})
hl.monitor({
    output = "eDP-1",
    disabled = false,
    mode = "1920x1080@60.00Hz",
    position = "3870x1100",
    scale = 1,
    cm = "srgb",
})

-- Autostart
hl.on("hyprland.start", function()
    hl.exec_cmd("hyprpm reload -n")
end)
